function Logo({ tag, collapsed }: { tag?: string; collapsed?: boolean }) {
  return (
    <Link href="/" className={`flex items-center gap-2.5 px-2 ${collapsed ? "lg:justify-center lg:px-0" : ""}`}>
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src="/logo.png"
        alt="Nxeon"
        style={{ height: 40, width: "auto" }}
        className={`select-none object-contain ${collapsed ? "lg:hidden" : ""}`}
      />
      {/* Compact mark, shown only when the desktop rail is collapsed. */}
      {/* eslint-disable-next-line @next/next/no-img-element */}
