        src="/favicon.svg"
        alt="Nxeon"
        style={{ height: 30, width: 30 }}
        className={`hidden select-none object-contain ${collapsed ? "lg:block" : ""}`}
      />
      {tag && (
        <span
          className={`rounded-md border border-amber-400/30 bg-amber-400/10 px-1.5 py-0.5 text-[10px] font-semibold uppercase tracking-widest text-amber-300 ${
            collapsed ? "lg:hidden" : ""
