  const [sidebarOpen, setSidebarOpen] = useState(false);
  // Desktop-only main-sidebar collapse. Persisted so it holds across every
  // portal page (mail, calendar, servers…). On mobile the drawer always renders
  // expanded — every collapse style below is gated to the `lg:` breakpoint.
  const [collapsed, setCollapsed] = useState(false);
  const [, startTransition] = useTransition();

  useEffect(() => {
    try {
      if (localStorage.getItem("nxeon.portal.railCollapsed") === "1") setCollapsed(true);
    } catch {}
  }, []);
  function toggleCollapsed() {
    setCollapsed((c) => {
      const next = !c;
      try {
        localStorage.setItem("nxeon.portal.railCollapsed", next ? "1" : "0");
      } catch {}
      return next;
    });
  }

