10	async function ensureReferralCode(userId: string, current: string | null): Promise<string> {
11	  if (current) return current;
12	  for (let i = 0; i < 6; i++) {
13	    const code = generateReferralCode();
14	    const clash = await db.user.findUnique({ where: { referralCode: code } });
15	    if (clash) continue;
16	    try {
17	      await db.user.update({ where: { id: userId }, data: { referralCode: code } });
18	      return code;
19	    } catch {
20	      /* unique clash race — retry */
21	    }
22	  }
23	  const fallback = generateReferralCode(12);
24	  await db.user.update({ where: { id: userId }, data: { referralCode: fallback } });
25	  return fallback;
26	}
