35	  ]);
36	
37	  const rewardCents = referralRewardCents();
38	  const appUrl = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/+$/, "");
39	  const link = `${appUrl}/register?ref=${code}`;
40	
41	  return (
