48	        code={code}
49	        rewardLabel={fmtMoney(rewardCents)}
50	        referredCount={referredCount}
51	        rewardedCount={rewardedCount}
52	      />
53	
54	      <div className="card">
55	        <p className="section-label mb-4">How it works</p>
56	        <ol className="space-y-3 text-sm text-slate-400">
57	          <li className="flex gap-3">
58	            <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full border border-brand-500/40 bg-brand-500/10 text-xs font-semibold text-brand-300">
