1	import { db } from "@/lib/db";
2	import { requireUser } from "@/lib/auth";
3	import { canAdministerOrg } from "@/lib/team-guard";
4	import { PageHeader, timeAgo } from "@/components/ui/primitives";
5	import TeamManager, { type OrgView } from "@/components/customer/TeamManager";
6	
7	export const dynamic = "force-dynamic";
8	
9	export default async function TeamPage() {
10	  const user = await requireUser();
11	
12	  // Every org the user owns or belongs to (owner always has an OWNER membership).
13	  const memberships = await db.membership.findMany({
14	    where: { userId: user.id },
15	    orderBy: { createdAt: "asc" },
16	    include: {
17	      org: {
18	        include: {
19	          owner: { select: { id: true, name: true } },
20	          members: {
21	            orderBy: { createdAt: "asc" },
22	            include: { user: { select: { id: true, name: true, email: true } } },
23	          },
24	        },
25	      },
26	    },
27	  });
28	
29	  const orgs: OrgView[] = memberships.map((m) => {
30	    const org = m.org;
31	    const iAdminister = canAdministerOrg(m.role);
32	    return {
33	      id: org.id,
34	      name: org.name,
35	      createdAgo: timeAgo(org.createdAt),
36	      ownerName: org.owner.name,
37	      myRole: m.role,
38	      canAdminister: iAdminister,
39	      isOwner: org.ownerId === user.id,
40	      members: org.members.map((mem) => {
41	        const isSelf = mem.userId === user.id;
42	        return {
43	          // The client is never given a co-member's `userId`. Combined with an
44	          // email address that was the whole attack: `verifyTotpForUser`
45	          // (QA-PRELAUNCH P0-2) took an arbitrary userId with no auth and no
46	          // rate limit, and this page used to hand one over for every member of
47	          // every org the viewer was in — an org they could have been added to
48	          // without consenting. The oracle is fixed; the ids still have no
49	          // business crossing to the browser, so role/remove are keyed by
50	          // membership id instead (see lib/actions-teams.ts).
51	          membershipId: iAdminister ? mem.id : null,
52	          name: mem.user.name,
53	          // Addresses go only to viewers entitled to them: someone who can
54	          // actually administer membership, plus your own row. A rank-and-file
55	          // MEMBER sees names, not a harvestable address list.
56	          email: iAdminister || isSelf ? mem.user.email : null,
57	          role: mem.role,
58	          isOwner: mem.userId === org.ownerId,
59	          isSelf,
60	          joinedAgo: timeAgo(mem.createdAt),
61	        };
62	      }),
63	    };
64	  });
65	
66	  return (
67	    <div className="space-y-6">
68	      <PageHeader
69	        title="Team"
70	        sub="Create organizations and invite teammates to your shared roster."
71	      />
72	      <TeamManager orgs={orgs} />
73	    </div>
74	  );
75	}
