12	/** Local-time first/last day of the current month grid (6 weeks), so the
13	 *  initial fetch matches the Month view the client opens on. */
14	function initialRange(): [string, string] {
15	  const now = new Date();
16	  const firstOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
17	  const gridStart = new Date(firstOfMonth);
18	  gridStart.setDate(gridStart.getDate() - gridStart.getDay());
19	  const gridEnd = new Date(gridStart);
20	  gridEnd.setDate(gridEnd.getDate() + 42);
21	  return [gridStart.toISOString(), gridEnd.toISOString()];
22	}
23	
24	export default async function CalendarPage() {
25	  await requireUser();
26	
27	  let calendars: CalendarInfo[] = [];
28	  let events: CalEvent[] = [];
29	  let tasks: TaskItem[] = [];
30	  let failed = false;
31	
32	  try {
33	    calendars = await listCalendars();
34	    if (calendars.length > 0) {
35	      const [start, end] = initialRange();
36	      [events, tasks] = await Promise.all([listEvents(start, end), listTasks()]);
37	    }
38	  } catch {
39	    failed = true;
40	  }
41	
42	  // An outage and an empty account are OPPOSITE situations and must not share a
43	  // screen: telling a paying mailbox owner whose CalDAV server hiccuped that they
44	  // have "no calendar connected" — and pushing them to buy email they already own
45	  // — hides the fault and sends them the wrong way. mail/page.tsx already splits
46	  // these; this page used to fold both into the empty state.
47	  if (failed) {
48	    return (
49	      <div className="mx-auto max-w-2xl pt-10">
50	        <EmptyState
51	          title="Couldn't reach your calendar"
52	          sub="We couldn't load your calendar just now — this is usually a brief hiccup on the calendar server, not a problem with your account. Reload in a moment; if it keeps happening, open a support ticket and we'll look into it."
53	          action={
54	            <Link href="/dashboard/calendar" className="btn-primary">
55	              Reload
56	            </Link>
57	          }
58	        />
59	      </div>
60	    );
61	  }
62	
63	  if (calendars.length === 0) {
64	    return (
65	      <div className="mx-auto max-w-2xl pt-10">
66	        <EmptyState
67	          title="No calendar connected"
68	          sub="Your calendar lives alongside your Nxeon mailbox. Set up business email on one of your domains to start scheduling events and tracking tasks here."
69	          action={
70	            <Link href="/dashboard/email" className="btn-primary">
71	              Set up email
72	            </Link>
73	          }
74	        />
75	      </div>
76	    );
77	  }
78	
79	  return (
80	    <CalendarClient initialCalendars={calendars} initialEvents={events} initialTasks={tasks} />
81	  );
82	}
