54	  if (!seconds || seconds <= 0) return "—";
55	  const d = Math.floor(seconds / 86400);
56	  const h = Math.floor((seconds % 86400) / 3600);
57	  const m = Math.floor((seconds % 3600) / 60);
58	  return d > 0 ? `${d}d ${h}h ${m}m` : h > 0 ? `${h}h ${m}m` : `${m}m`;
59	}
